```sql
SELECT t1.name, t1.capacity, COUNT(*) AS concert_count FROM concert AS t2 JOIN stadium AS t1 ON t2.stadium_id = t1.stadium_id WHERE t2.year > '2013' GROUP BY t2.stadium_id ORDER BY concert_count DESC LIMIT 1;
```

